import { initiate_project_transfer_ownership } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    tranferOwnerDialog: Boolean,
    rowInfo: Object,
    allUSersNames: Array
  },
  data() {
    return {
      selectUser: "",
      userItems: [],
      loading: false
    };
  },
  watch: {
    tranferOwnerDialog: {
      async handler() {
        if (this.tranferOwnerDialog == true) {
          this.userItems = [];
          this.allUSersNames.forEach(element => {
            if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT" && element.user_email_id != this.rowInfo.dashboard_created_by) {
              this.userItems.push({
                full_user_name: element.full_user_name,
                user_email_id: element.user_email_id
              });
            }
          });
        }
      },
      immediate: true
    }
  },
  methods: {
    async validate_data() {
      const isValid = await this.$refs.forms.validate();
      if (isValid) {
        await this.transfer_ownership();
      }
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.forms.reset();
      this.$refs.forms.resetValidation();
    },
    async transfer_ownership() {
      this.loading = true;

      //   var data = this.$store.getters.GetUserObj;

      try {
        let result = await API.graphql(graphqlOperation(initiate_project_transfer_ownership, {
          input: {
            //   organization_id: data.organization.organization_id,
            project_id: this.rowInfo.project_id,
            transfer_to_email: this.selectUser
            //   current_user_email:data.user.user_email_id,
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.initiate_project_transfer_ownership);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.forms.reset();
          this.$refs.forms.resetValidation();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
